class Solution { fun flipgame(fronts:IntArray,backs:IntArray):Int{val forbidden=mutableSetOf<Int>();for(i in fronts.indices)if(fronts[i]==backs[i])forbidden.add(fronts[i]);var answer=Int.MAX_VALUE;for(value in fronts)if(value !in forbidden)answer=minOf(answer,value);for(value in backs)if(value !in forbidden)answer=minOf(answer,value);return if(answer==Int.MAX_VALUE)0 else answer} }
